/* Editorial legal analysis. Sources checked 20 October 2026; no live-law lookup. */
const legalSources={base:'https://www.nxpc.or.th/wp-content/uploads/2022/07/พรบ-สภานโยบาย-อววน-1.pdf',amendment:'https://www.nxpc.or.th/wp-content/uploads/2025/03/06_พรบ-สภานโยบาย-ฉบับที่-2.pdf',catalog:'https://www.nxpc.or.th/content/law/10387',higher:'https://www.nxpc.or.th/content/law/10391'};
function lawRef(which,label,page){return `<a class="law-ref" href="${legalSources[which]}${page?'#page='+page:''}" target="_blank" rel="noopener">${label} ↗</a>`}
function legalAnalysis(){return `<section class="hero law-hero"><div class="eyebrow">LEGAL ANALYSIS · ฉบับหลักและฉบับแก้ไข</div><h1>สภานโยบาย อววน.<br><em>จากโครงสร้างปี 2562 สู่การแก้ไขปี 2568</em></h1><p>บทวิเคราะห์พระราชบัญญัติสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ พ.ศ. 2562 และ (ฉบับที่ 2) พ.ศ. 2568</p></section>
<div class="law-meta"><span>ตรวจแหล่งข้อมูล: 20 ตุลาคม 2569</span><span>บทวิเคราะห์เชิงวิชาการ • ไม่ใช่คำวินิจฉัยของหน่วยงาน</span><button class="textbutton" id="download-analysis">ดาวน์โหลดบทวิเคราะห์ .txt ↓</button></div>
<div class="law-callout"><strong>ประเด็นสำคัญ: ฉบับที่ 2 แก้มาตรา 12 (1) เท่านั้น</strong><p>ขยายกลไกพิจารณางบประมาณด้านการอุดมศึกษาให้ครอบคลุมคำของบประมาณของกองทุนเพื่อพัฒนาการอุดมศึกษา มิใช่การยกเลิกหรือเขียนโครงสร้าง กสว. และ สกสว. ใหม่ทั้งระบบ ${lawRef('amendment','ฉบับที่ 2 ม.3 • ราชกิจจาฯ หน้า 4–5',1)}</p></div>
<nav class="law-toc" aria-label="สารบัญบทวิเคราะห์">${[['law-overview','01 ภาพรวม'],['law-comparison','02 สิ่งที่เปลี่ยน'],['law-interpret','03 การตีความ'],['law-example','04 ตัวอย่าง'],['law-cautions','05 ข้อควรระวัง'],['law-action','06 แนวปฏิบัติ']].map(([id,label])=>`<a href="#${id}">${label}</a>`).join('')}</nav>
<section id="law-overview" class="panel knowledge law-section"><span class="eyebrow">01 / กฎหมายกล่าวว่าอย่างไร</span><h2>โครงสร้างเดิมยังเป็นฐานในการอ่านฉบับแก้ไข</h2><div class="law-two"><div><h3>ฉบับหลัก พ.ศ. 2562</h3><p>ประกาศในราชกิจจานุเบกษา เล่ม 136 ตอนที่ 57 ก วันที่ 1 พฤษภาคม 2562 หน้า 8–41 มี 80 มาตรา แบ่งเป็น 4 หมวดและบทเฉพาะกาล ใช้บังคับวันที่ 2 พฤษภาคม 2562 ตามมาตรา 2 โดยจัดระบบนโยบาย งบประมาณ หน่วยงานสนับสนุน และกองทุน ววน. ${lawRef('base','ฉบับหลัก • หน้า 8',1)}</p></div><div><h3>ฉบับที่ 2 พ.ศ. 2568</h3><p>ประกาศในราชกิจจานุเบกษา เล่ม 142 ตอนที่ 14 ก วันที่ 24 มีนาคม 2568 หน้า 4–6 มี 3 มาตรา ใช้บังคับวันที่ 25 มีนาคม 2568 ตามมาตรา 2 และใช้มาตรา 3 แทนที่มาตรา 12 (1) ของฉบับหลัก ${lawRef('amendment','ฉบับที่ 2 • หน้า 4–6',1)}</p></div></div><p><b>ความสัมพันธ์ทางกฎหมาย:</b> ทั้งสองฉบับเป็นพระราชบัญญัติระดับเดียวกัน ฉบับที่ 2 เป็นกฎหมายแก้ไขเพิ่มเติม จึงอ่านฉบับหลักโดยแทนข้อความมาตรา 12 (1) ด้วยข้อความใหม่ตั้งแต่วันใช้บังคับ ส่วนมาตราอื่นไม่ได้ถูกแก้โดยฉบับที่ 2 นี้ ไม่ใช่กรณีกฎหมายแม่บทกับกฎหมายลำดับรอง</p><h3>แยกบทบาท ก่อนเชื่อมโยงอำนาจ</h3><div class="law-tablewrap"><table class="law-table"><caption>สรุปหน้าที่ตามฉบับหลัก พ.ศ. 2562</caption><thead><tr><th>กลไก / หน่วยงาน</th><th>หน้าที่โดยสรุป</th><th>ฐานกฎหมาย</th></tr></thead><tbody>
<tr><td>สภานโยบาย อววน.</td><td>เสนอนโยบายและแผนต่อ ครม. ให้ความเห็นชอบกรอบวงเงิน และกำกับทิศทางให้เชื่อมโยงกัน จัดให้มีการติดตามประเมินผล</td><td>${lawRef('base','ม.11 (1)–(3), (6)',6)}</td></tr>
<tr><td>สอวช.</td><td>สนับสนุนงานวิชาการและธุรการของสภานโยบาย พร้อมเสนอความเห็นด้านนโยบายและกรอบงบประมาณ</td><td>${lawRef('base','ม.21–22',10)}</td></tr>
<tr><td>กสว.</td><td>เสนอแนะด้าน ววน. บริหารกองทุน ววน. และพิจารณาคำขอพร้อมจัดสรรงบประมาณจากกองทุนแก่หน่วยงานตามหลักเกณฑ์</td><td>${lawRef('base','ม.41 (1)–(7)',18)}</td></tr>
<tr><td>สกสว.</td><td>เป็นนิติบุคคลของรัฐ สนับสนุน กสว. จัดทำคำของบประมาณกองทุน และกลั่นกรองคำขอของหน่วยงานในระบบ โดยมาตรา 43 กำหนดไม่ให้ดำเนินการวิจัยเอง</td><td>${lawRef('base','ม.43–44 โดยเฉพาะ (1), (5)–(7)',20)}</td></tr>
<tr><td>กองทุนส่งเสริม ววน.</td><td>ตั้งขึ้นใน สกสว. เพื่อส่งเสริมระบบวิจัยและนวัตกรรม การใช้เงินและจัดสรรอยู่ภายใต้วัตถุประสงค์และเงื่อนไขที่กฎหมายกำหนด</td><td>${lawRef('base','ม.54, 57–59',24)}</td></tr></tbody></table></div></section>
<section id="law-comparison" class="panel knowledge law-section"><span class="eyebrow">02 / แปลภาษากฎหมายให้เข้าใจง่าย</span><h2>ตารางเปรียบเทียบมาตรา 12 (1)</h2><p>ตารางเป็นการสรุปความ ไม่ใช่การคัดตัวบท ควรเปิดเอกสารต้นฉบับประกอบ ${lawRef('base','ข้อความเดิม • หน้า 14',7)} ${lawRef('amendment','ข้อความใหม่ • หน้า 4–5',1)}</p><div class="law-tablewrap"><table class="law-table"><thead><tr><th>ประเด็น</th><th>ฉบับหลัก พ.ศ. 2562</th><th>เมื่อแก้ไข พ.ศ. 2568</th></tr></thead><tbody>
<tr><td>ที่มาของคณะกรรมการ</td><td>นายกรัฐมนตรีแต่งตั้งโดยข้อเสนอของรัฐมนตรีและคณะกรรมการการอุดมศึกษา</td><td>คงกลไกนี้ไว้</td></tr>
<tr><td>องค์ประกอบ</td><td>ประธานตามมติสภานโยบาย ผู้แทน กกอ. ไม่เกิน 2 คน ผู้แทนสำนักงบประมาณไม่เกิน 2 คน และปลัด อว. เป็นกรรมการและเลขานุการ อาจมีผู้ช่วยเลขานุการจากสำนักงบประมาณ</td><td>คงองค์ประกอบและกลไกผู้ช่วยเลขานุการดังกล่าว</td></tr>
<tr><td>สิ่งที่คณะกรรมการพิจารณา</td><td>คำของบประมาณของสถาบันอุดมศึกษาทุกแห่งในความรับผิดชอบของกระทรวง เฉพาะงบลงทุนและงบเงินอุดหนุนเพื่อพัฒนาความเป็นเลิศและผลิตกำลังคนระดับสูงเฉพาะทางตามที่ระบุ</td><td><b>เปลี่ยนเป็นพิจารณาคำของบประมาณของกองทุนเพื่อพัฒนาการอุดมศึกษาตามกฎหมายว่าด้วยการอุดมศึกษา</b></td></tr>
<tr><td>เส้นทางหลังพิจารณา</td><td>เสนอไปยังสำนักงบประมาณเพื่อเสนอ ครม.</td><td>คงเส้นทางนี้ไว้ การพิจารณาไม่ใช่การอนุมัติเบิกจ่ายแก่ผู้ขอโดยอัตโนมัติ</td></tr>
<tr><td>งบประมาณด้าน ววน. ใน ม.12 (2)</td><td>มีกลไกคณะกรรมการพิจารณางบประมาณด้าน ววน. แยกต่างหาก</td><td>ฉบับที่ 2 ไม่ได้แก้ไข ม.12 (2)</td></tr></tbody></table></div><p><b>ภาษาง่าย:</b> ประตูพิจารณางบประมาณด้านการอุดมศึกษาเดิมตรวจคำขอบางประเภทรายสถาบัน เมื่อแก้ไขแล้วตรวจคำขอของกองทุนเพื่อพัฒนาการอุดมศึกษา ส่วนการที่สถาบันจะรับเงินกองทุนต้องดูเงื่อนไขในกฎหมายว่าด้วยการอุดมศึกษาและหลักเกณฑ์ที่เกี่ยวข้องเพิ่มเติม</p><div class="law-callout light"><strong>เจตนารมณ์ที่มีหลักฐาน</strong><p>หมายเหตุท้ายฉบับที่ 2 ระบุความจำเป็นในการปรับหน้าที่และอำนาจของคณะกรรมการให้สอดคล้องกับการมีกองทุนเพื่อพัฒนาการอุดมศึกษาตามกฎหมายว่าด้วยการอุดมศึกษา หมายเหตุช่วยอธิบายเหตุผลของการแก้ไข แต่ไม่ใช่บทบัญญัติให้อำนาจจ่ายเงินด้วยตัวเอง ${lawRef('amendment','หมายเหตุ • หน้า 6',3)}</p></div></section>
<section id="law-interpret" class="panel knowledge law-section"><span class="eyebrow">03 / การตีความทางนิติศาสตร์</span><h2>อ่านความเปลี่ยนแปลงผ่าน 6 มิติ</h2><div class="law-two">${[
['ตามถ้อยคำ','ข้อความใหม่ระบุคำของบประมาณ “ของกองทุนเพื่อพัฒนาการอุดมศึกษา” จึงไม่ควรอ่านเสมือนยังเป็นรายการคำขอของทุกสถาบันตามข้อความเดิม และคำว่า “พิจารณา” ต้องอ่านต่อกับขั้นเสนอไปยังสำนักงบประมาณเพื่อเสนอ ครม.'],
['ตามเจตนารมณ์','เหตุผลท้ายฉบับแก้ไขสนับสนุนการปรับกลไกพิจารณางบประมาณให้สอดคล้องกับกองทุนที่จัดตั้งตามกฎหมายว่าด้วยการอุดมศึกษา ไม่ใช่หลักฐานว่าตั้งใจโอนอำนาจจัดสรรกองทุน ววน. ทั้งหมดไปยังคณะกรรมการด้านการอุดมศึกษา'],
['เชิงระบบ','ต้องอ่าน ม.12 (1) ใหม่ร่วมกับ ม.11 (2) เรื่องกรอบวงเงิน ม.12 (2) เรื่อง ววน. และ ม.13 ที่ส่งต่อวิธีทำคำขอและจัดสรรไปยังกฎหมายเฉพาะตามประเภทของงาน'],
['ตามบริบท','ต้องทราบก่อนว่าเป็นคำของบประมาณระดับกองทุน คำขอรับเงินของสถาบัน หรือการเบิกจ่ายตามสัญญา เพราะเป็นคนละขั้น และต้องจำแนกแหล่งเงินด้านการอุดมศึกษากับด้าน ววน.'],
['ตามหลักกฎหมาย','ใช้ข้อความใหม่ในส่วนที่แก้เมื่อมีผลบังคับ ไม่ขยายอำนาจจากเจตนารมณ์เกินตัวบท ข้อกำหนดลำดับรองต้องมีฐานอำนาจและไม่ขัดพระราชบัญญัติ มติหรือคู่มือไม่กลายเป็นกฎหมายโดยชื่อเอกสารเพียงอย่างเดียว'],
['เพื่อการบังคับใช้','ตรวจประเภทคำขอ ผู้มีอำนาจแต่งตั้งคณะกรรมการ คำสั่งแต่งตั้งที่มีผล หลักเกณฑ์ที่ใช้ และหลักฐานการพิจารณาก่อนส่งต่อ ต้องตรวจปฏิทินงบประมาณจริง เพราะฉบับที่ 2 ไม่ได้กำหนดเส้นตายรายวันสำหรับการยื่นคำขอ']
].map(([t,p])=>`<article><h3>${t}</h3><p>${p}</p></article>`).join('')}</div><p class="law-note">เนื้อหาในส่วนนี้เป็นการตีความเชิงวิชาการจากตัวบทและหมายเหตุ ไม่ใช่ถ้อยคำในพระราชบัญญัติ และไม่ยืนยันว่ามีแนวคำพิพากษาหรือคำวินิจฉัยรองรับทุกประเด็น ${lawRef('base','ม.11–13 • หน้า 13–15',6)} ${lawRef('amendment','ฉบับแก้ไขทั้งฉบับ',1)}</p></section>
<section id="law-example" class="panel knowledge law-section"><span class="eyebrow">04 / ตัวอย่างการใช้กฎหมาย</span><h2>สองกองทุน สองเส้นทางที่ต้องจำแนก</h2><div class="law-two"><article><h3>กรณีสมมติ A: พัฒนาหลักสูตรกำลังคนระดับสูง</h3><p><b>ข้อสมมติ:</b> สถาบันอุดมศึกษาต้องการขอเงินจากกองทุนเพื่อพัฒนาการอุดมศึกษา ไม่ใช่การขอจากกองทุน ววน.</p><p><b>วิธีพิจารณา:</b> ตรวจเกณฑ์กองทุนตามกฎหมายว่าด้วยการอุดมศึกษาก่อน มาตรา 12 (1) ใหม่รองรับการพิจารณาคำของบประมาณของกองทุน มิได้ทำให้คำขอรายโครงการได้รับอนุมัติทันที ต้องแยกขั้นคำของบประมาณกองทุนออกจากขั้นจัดสรรแก่สถาบัน</p></article><article><h3>กรณีสมมติ B: วิจัยเพื่อแก้ปัญหาชุมชน</h3><p><b>ข้อสมมติ:</b> หน่วยงานในระบบวิจัยและนวัตกรรมเสนอขอเงินจากกองทุนส่งเสริม ววน.</p><p><b>วิธีพิจารณา:</b> พิจารณา ม.12 (2), ม.41 (4), (7), ม.44 (5)–(7) และ ม.54, 57–59 พร้อมหลักเกณฑ์ที่ใช้กับคำขอนั้น ไม่สรุปว่าต้องย้ายไปสู่กลไกด้านการอุดมศึกษาเพียงเพราะผู้ขอเป็นมหาวิทยาลัย</p></article></div><p>ตัวอย่างเป็นการสาธิตวิธีแยกประเด็น ยังไม่ใช่ผลวินิจฉัยสิทธิได้รับทุนของผู้ขอรายใด ${lawRef('base','ฐานอำนาจและกองทุน • ฉบับหลัก',1)} ${lawRef('amendment','ขอบเขตการแก้ไข',1)}</p></section>
<section id="law-cautions" class="panel knowledge law-section"><span class="eyebrow">05 / ข้อควรระวัง</span><h2>สิ่งที่ยังสรุปจากกฎหมายสองฉบับนี้ไม่ได้</h2><ul><li><b>ไม่ใช่กองทุนเดียวกัน:</b> กองทุนเพื่อพัฒนาการอุดมศึกษาตาม ม.12 (1) ใหม่ กับกองทุนส่งเสริม ววน. ตาม ม.54 มีฐานอำนาจและกลไกต่างกัน</li><li><b>ไม่ใช่อำนาจอนุมัติทุกขั้น:</b> การให้ความเห็นชอบกรอบวงเงิน การพิจารณาคำของบประมาณ การจัดสรร และการเบิกจ่ายต้องแยกผู้มีอำนาจและหลักเกณฑ์</li><li><b>ไม่รับรองเอกสารเดิมทุกฉบับ:</b> ม.80 ของฉบับหลักคงผลของเอกสารเดิมบางประเภทโดยมีเงื่อนไขว่าไม่ขัดหรือแย้ง และจนกว่าจะมีเอกสารใหม่ ต้องตรวจฉบับที่ใช้จริง ไม่ใช่ถือว่าทุกคู่มือยังใช้ได้</li><li><b>บทเฉพาะกาล:</b> ฉบับหลักมี ม.66–80 ส่วนฉบับที่ 2 มีเพียง 3 มาตราและไม่มีบทเฉพาะกาลเฉพาะสำหรับคำขอค้างพิจารณา จึงยังสรุปไม่ได้ว่าคำขอค้างทุกเรื่องต้องใช้ขั้นตอนเดิมหรือใหม่เหมือนกัน</li><li><b>ขอบเขตการตรวจ:</b> บทนี้ตรวจฉบับหลัก ฉบับที่ 2 และทะเบียนเผยแพร่ของสภานโยบาย ไม่ใช่การรับรองว่าได้ตรวจครบกฎหมายลำดับรอง คำสั่งแต่งตั้ง แนววินิจฉัย และการแก้ไขทุกฉบับถึงวันนำไปใช้จริง</li></ul><p>${lawRef('base','ม.12, 41, 44, 54 และ 80',1)} ${lawRef('amendment','ฉบับที่ 2 • 3 มาตรา',1)}</p></section>
<section id="law-action" class="panel knowledge law-section"><span class="eyebrow">06 / ข้อสรุปและแนวทางปฏิบัติ</span><h2>รายการตรวจสอบสำหรับผู้บริหารและ สกสว.</h2><div class="law-checklist">${[
'ระบุแหล่งเงินและระดับของคำขอให้ชัด: ระดับกองทุน ระดับหน่วยงาน หรือระดับโครงการ',
'บันทึกวันที่เกิดเรื่อง วันที่ยื่นคำขอ และขั้นตอนที่ดำเนินไปแล้ว โดยเฉพาะเรื่องคาบเกี่ยว 25 มีนาคม 2568',
'เลือกฐานอำนาจให้ตรง: ม.12 (1) ใหม่สำหรับกลไกงบอุดมศึกษา หรือ ม.12 (2) และบทเกี่ยวกับกองทุน ววน.',
'ตรวจคำสั่งแต่งตั้ง มอบหมาย ผู้ลงนาม และหลักเกณฑ์ปัจจุบัน ไม่ใช้ชื่อคณะกรรมการแทนการตรวจอำนาจ',
'สำหรับ สกสว. แยกงานจัดทำและกลั่นกรองคำขอของสำนักงานตาม ม.44 ออกจากอำนาจของ กสว. ตาม ม.41',
'เชื่อมรายการกับแผน กรอบวงเงิน และหลักฐานผลสัมฤทธิ์ เก็บบันทึกเหตุผลและเอกสารที่ตรวจสอบย้อนหลังได้',
'ตรวจหน้าที่รายงานประจำปีของ สอวช./สกสว. ตาม ม.52 ซึ่งกำหนดภายใน 180 วันนับแต่สิ้นปีงบประมาณ พร้อมการเผยแพร่ต่อสาธารณชน',
'กรณีคำขอค้างหรือมีข้อโต้แย้งเรื่องอำนาจ ให้ฝ่ายกฎหมายหรือหน่วยงานผู้มีอำนาจตรวจเอกสารเฉพาะเรื่องก่อนตัดสินใจ'
].map(t=>`<label><input type="checkbox"> <span>${t}</span></label>`).join('')}</div><p class="law-note">ช่องทำเครื่องหมายใช้ช่วยอ่านในหน้านี้ ไม่บันทึกข้ามการเปิดหน้า รายการตรวจสอบเป็นข้อเสนอแนะในการทำงาน ยกเว้นหน้าที่และเวลาที่อ้างกฎหมายโดยตรง ${lawRef('base','ม.41, 44, 52 • โดย ม.52 อยู่หน้า 30',23)}</p><button class="primary" data-ask="โปรดวิเคราะห์การแบ่งหน้าที่ระหว่าง กสว. และ สกสว. ตามมาตรา 41 และ 44 และเปรียบเทียบเส้นทางคำของบประมาณตามมาตรา 12 (1) ซึ่งแก้ไขโดย พ.ร.บ.สภานโยบายฯ (ฉบับที่ 2) พ.ศ. 2568 กับมาตรา 12 (2) โดยแยกกองทุนเพื่อพัฒนาการอุดมศึกษาจากกองทุนส่งเสริม ววน. และตรวจตัวบทจากแหล่งทางการก่อนยืนยันผลใช้บังคับ">นำประเด็นนี้ไปตั้งคำถามต่อ →</button></section>
<section class="panel knowledge law-section"><span class="eyebrow">SOURCE REGISTER</span><h2>เอกสารอ้างอิงที่ตรวจสอบได้</h2><ol><li>${lawRef('base','สำเนาราชกิจจานุเบกษา พ.ร.บ. พ.ศ. 2562 บนเว็บไซต์สภานโยบาย',1)}<br>34 หน้า • หน้าเลขราชกิจจาฯ 8–41 • ใช้อ้างอิงตัวบทเดิม โครงสร้าง และบทเฉพาะกาล</li><li>${lawRef('amendment','สำเนาราชกิจจานุเบกษา พ.ร.บ. (ฉบับที่ 2) พ.ศ. 2568',1)}<br>3 หน้า • หน้าเลขราชกิจจาฯ 4–6 • ตรวจภาพต้นฉบับ เนื่องจากข้อความที่สกัดจาก PDF บางส่วนอ่านคลาดเคลื่อน</li><li>${lawRef('catalog','หน้าทะเบียนกฎหมายฉบับที่ 2 ของสภานโยบาย')}<br>ใช้ตรวจประกอบข้อมูลวันประกาศและวันใช้บังคับ</li><li>${lawRef('higher','เอกสารเชื่อมโยง: พ.ร.บ.การอุดมศึกษา (ฉบับที่ 2) พ.ศ. 2568')}<br>เป็นกฎหมายอีกฉบับสำหรับค้นคว้าต่อ รายละเอียดเงื่อนไขกองทุนตามกฎหมายนี้ไม่ได้วิเคราะห์ครบในบทนี้</li></ol><p class="law-note">ใช้เลขมาตราเป็นหลักในการอ้างอิง เลขหน้าในลิงก์ PDF เป็นตำแหน่งเปิดอ่าน ซึ่งอาจแตกต่างจากเลขหน้าราชกิจจานุเบกษาที่พิมพ์บนเอกสาร</p></section>`}
document.addEventListener('click',e=>{if(e.target.closest('#download-analysis')){const text=document.querySelector('#content').innerText+'\n\nลิงก์เอกสารอ้างอิง\n'+Object.entries(legalSources).map(([k,v])=>k+': '+v).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='Thai-Legal-Wisdom-Acts-2562-2568.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}});
